 291	    config: &Arc<Config>,
 292	    ts: &Toolset,
 293	    force: bool,
 294	    requested_scope: ShimScope,
 295	) -> Result<()> {
 296	    let user_shims = dirs::shims();
 297	    let system_shims = dirs::system_shims();
 298	    let collocated = file::paths_eq(&user_shims, &system_shims);
 299	    let scope = if collocated {
 300	        ShimScope::Both
 301	    } else {
 302	        requested_scope
 303	    };
 304	    let shims_dir = match requested_scope {
 305	        ShimScope::User | ShimScope::Both => user_shims,
 306	        ShimScope::System => system_shims,
 307	    };
 308	    let _lock = LockFile::new(&shims_dir)
 309	        .with_callback(|l| {
 310	            trace!("reshim callback {}", l.display());
 311	        })
 312	        .lock();
 313	
 314	    let mise_bin = mise_bin_for_shims();
 315	    let mise_bin = mise_bin.absolutize()?; // relative paths don't work as shims
 316	
 317	    #[cfg(windows)]
 318	    let shim_mode = effective_shim_mode(&mise_bin);
 319	    #[cfg(not(windows))]
 320	    let shim_mode = String::new();
 321	    let shim_mode_changed = cfg!(windows) && {
 322	        let mode_file = shims_dir.join(".mode");
 323	        mode_file
 324	            .exists()
 325	            .then(|| fs::read_to_string(&mode_file).unwrap_or_default())
 326	            .is_some_and(|prev| prev.trim() != shim_mode)
 327	    };
 328	    // On Windows, "exe"/"hardlink" shims are literal copies of the mise(-shim)
 329	    // binary, so they go stale when mise is updated (by self-update or an
 330	    // external package manager) until a forced reshim. Track the mise version
 331	    // that generated the shims in a `.version` marker (mirroring `.mode`) and
 332	    // rebuild from scratch whenever it changes. The marker is written by
 333	    // whichever binary runs reshim, so after an update the new binary stamps
 334	    // the new version. See discussion #10022.
 335	    let shim_version = env!("CARGO_PKG_VERSION");
 336	    let shim_version_changed = cfg!(windows) && {
 337	        let version_file = shims_dir.join(".version");
 338	        let prev = fs::read_to_string(&version_file).ok();
 339	        shim_version_stale(prev.as_deref(), shim_version, &shim_mode)
 340	    };
 341	    if force || shim_mode_changed || shim_version_changed {
 342	        // On Windows, .exe shims may be locked by processes or the shell (they
 343	        // are on PATH).  Instead of removing the entire directory (which fails
 344	        // with "Access is denied"), remove individual files with a rename-first
 345	        // fallback so locked executables are moved out of the way.
 346	        if cfg!(windows) {
 347	            remove_shims_individually(&shims_dir)?;
 348	        } else {
 349	            file::remove_all(&shims_dir)?;
 350	        }
 351	    }
 352	    file::create_dir_all(&shims_dir)?;
 353	    if cfg!(windows) {
 354	        let mode_file = shims_dir.join(".mode");
 355	        file::write(&mode_file, &shim_mode)?;
 356	        // Written for every shim mode (like `.mode`) even though it is only
 357	        // consulted for "exe"/"hardlink" modes; for "file"/"symlink" it is
 358	        // harmless and keeps the marker current if the mode later changes
 359	        // (mode transitions themselves are handled by `shim_mode_changed`).
 360	        let version_file = shims_dir.join(".version");
 361	        file::write(&version_file, shim_version)?;
