 105	    fn activate_shims(&self, shell: &dyn Shell, mise_bin: &Path) -> std::io::Result<()> {
 106	        let exe_dir = mise_bin.parent().unwrap();
 107	        let user_shims = dirs::shims();
 108	        let system_shims = dirs::system_shims();
 109	        let mut shim_dirs = vec![user_shims];
 110	        if system_shims.is_dir() && !file::paths_eq(&shim_dirs[0], &system_shims) {
 111	            shim_dirs.push(system_shims);
 112	        }
 113	        let mut prelude = vec![];
 114	        // The shims dir is always (move-)prepended so it stays at the front of PATH
 115	        // even when activation is re-sourced (e.g. VS Code terminals) — see #8757.
 116	        // The mise executable's own dir only needs to be present so `mise` is
 117	        // callable, so it uses the guarded prepend: this avoids re-prepending (and
 118	        // thereby reordering) a system dir such as /usr/bin that is already in PATH
 119	        // for deb/rpm installs, which would otherwise move it ahead of
 120	        // /usr/local/bin (#10264).
 121	        let prepended_exe_dir = if let Some(p) = self.prepend_path(exe_dir) {
 122	            prelude.push(p);
 123	            true
 124	        } else {
 125	            false
 126	        };
 127	        let has_command_wrappers = dirs::COMMAND_WRAPPERS.is_dir();
 128	        let mut dispatch_dirs = shim_dirs.iter().map(PathBuf::as_path).collect::<Vec<_>>();
 129	        if has_command_wrappers {
 130	            dispatch_dirs.insert(0, dirs::COMMAND_WRAPPERS.as_path());
 131	        }
 132	        let dispatch_dirs_already_first = are_dirs_first_in_paths(&env::PATH, &dispatch_dirs);
 133	        if shell.supports_move_path() || prepended_exe_dir || !dispatch_dirs_already_first {
 134	            // Prepend in reverse order so user shims retain precedence over system
 135	            // shims in shells where each operation inserts at the front.
 136	            let mut path_changed = prepended_exe_dir;
 137	            for shims_dir in shim_dirs.iter().rev() {
 138	                if let Some(p) = self.shims_prepend_path(shell, shims_dir, path_changed) {
 139	                    prelude.push(p);
 140	                    path_changed = true;
 141	                }
 142	            }
 143	            if has_command_wrappers
 144	                && let Some(p) = self.shims_prepend_path(shell, &dirs::COMMAND_WRAPPERS, true)
 145	            {
 146	                prelude.push(p);
 147	            }
 148	        }
