                .and_then(|matches| matches.last())
        {
            return build(v.clone());
        }
        if matches!(
            request.source(),
            ToolSource::IdiomaticVersionFile(path)
                if crate::config::config_file::idiomatic_version::package_json::is_package_json(path)
        ) && crate::semver::is_npm_semver_range_query(&v)
        {
            if !opts.latest_versions && !should_filter_installed_versions {
                let installed_versions = backend.list_installed_versions();
                if let Some(matches) =
                    crate::semver::npm_semver_range_filter(&installed_versions, &v)
                    && let Some(v) = matches.last()
                {
                    return build(v.clone());
                }
            }
            if !is_offline {
                let versions = match opts.before_date {
                    Some(before) => {
                        let versions_with_info = backend
                            .list_remote_versions_with_info_with_refresh(
                                config,
                                opts.refresh_remote_versions,
                            )
                            .await?;
                        VersionInfo::filter_by_date(versions_with_info, before)
                            .into_iter()
                            .map(|v| v.version)
                            .collect()
                    }
                    None => {
                        backend
                            .list_remote_versions_with_refresh(config, opts.refresh_remote_versions)
                            .await?
                    }
                };
                if let Some(matches) = crate::semver::npm_semver_range_filter(&versions, &v)
                    && let Some(v) = matches.last()
                {
                    return build(v.clone());
                }
            }
        }
        // When OFFLINE, skip ALL remote version fetching regardless of version format
        if is_offline {
            return build(v);
        }
        // In prefer-offline mode (hook-env, activate, exec), skip remote version
        // fetching for fully-qualified versions (e.g. "2.3.2") that aren't installed.
        // Prefix versions like "2" still need remote resolution to find e.g. "2.1.0".
        // "latest" also needs remote resolution but is handled in the block above.
        if prefer_offline && !opts.latest_versions && v.matches('.').count() >= 2 {
            return build(v);
        }
        // Exact pinned versions do not need the full versions list when the
        // backend can validate them directly or defer validation to its
        // installer. This also keeps explicit pins outside release-age
        // filtering. If the backend returns None, fall through to normal
        // prefix resolution so requests like "1.2.3" can still resolve to
        // "1.2.3.4" when that is the latest matching version.
        if (v.matches('.').count() >= 2 || backend.is_exact_version(&v))
            && let Some(v) = backend.resolve_exact_version(config, &v).await?
        {
            return build(v);
        }
        // First try with date filter (common case)
        let matches = match pin_remote_matches {
            Some(matches) => matches,
            None => {
                backend
                    .list_versions_matching_with_opts(
                        config,
                        &v,
        .await?;
        Box::pin(Self::resolve_version(config, request, &v, opts)).await
    }

    async fn resolve_prefix(
        config: &Arc<Config>,
        request: ToolRequest,
        prefix: &str,
        opts: &ResolveOptions,
    ) -> Result<Self> {
        let backend = request.backend()?;
        let settings = Settings::get();
        let is_offline = settings.offline() || opts.offline;
        let prefer_offline =
            settings.prefer_offline() && !matches!(request.source(), ToolSource::Argument);
        let should_filter_installed_versions = opts.filter_installed_versions_by_release_date
            && opts.before_date.is_some()
            && !opts.before_date_from_default
            && !is_offline
            && !prefer_offline;
        if !opts.latest_versions
            && !should_filter_installed_versions
            && let Some(v) = backend.list_installed_versions_matching(prefix).last()
        {
            return Ok(Self::new(request, v.to_string()));
        }
        if opts.offline {
            return Ok(Self::new(request, prefix.to_string()));
        }
        let matches = backend
            .list_versions_matching_with_opts(
                config,
                prefix,
                opts.before_date,
                opts.refresh_remote_versions,
            )
            .await?;
        let v = matches
            .last()
            .ok_or_else(|| Self::no_versions_found(&backend, opts.before_date))?;
        Ok(Self::new(request, v.to_string()))
    pub(crate) fn local_resolve(&self, config: &Config, v: &str) -> eyre::Result<Option<String>> {
        if let Some(lt) = self.lockfile_resolve(config)? {
            return Ok(Some(lt.version));
        }
        if let Some(backend) = backend::get(self.ba()) {
            let matches = backend.list_installed_versions_matching(v);
            if matches.iter().any(|m| m == v) {
                return Ok(Some(v.to_string()));
            }
            if let Some(v) = matches.last() {
                return Ok(Some(v.to_string()));
            }
        }
        Ok(None)
    }

    pub(crate) async fn resolve(
        &self,
        config: &Arc<Config>,
        opts: &ResolveOptions,
    ) -> Result<ToolVersion> {
        ToolVersion::resolve(config, self.clone(), opts).await
    }

    pub(crate) fn resolve_options(&self, opts: &ResolveOptions) -> Result<ResolveOptions> {
        let minimum_release_age = self.options().minimum_release_age().map(str::to_string);
        let mut opts = opts.clone();
        opts.apply_before_date_for_tool(self.ba(), minimum_release_age.as_deref())?;
        Ok(opts)
    }

    pub(crate) fn is_os_supported(&self) -> bool {
        if let Some(os_list) = self.os() {
            let matched = os_list
                .iter()
                .any(|entry| crate::cli::version::os_selector_matches(entry));
            if !matched {
                return false;
            }
        }
        self.ba().is_os_supported()
    }
}

/// Reject version strings that contain shell-quote-breaking characters,
/// control characters, or path-traversal sequences. Version strings flow into
/// install path names and (for vfox plugins) into `ctx.version` / `ctx.rootPath`
/// values that downstream Lua hooks often interpolate into shell commands.
///
/// The deny list is the minimum set of characters that can break out of either
/// a single- or double-quoted shell string, or that trigger expansion *inside*
use std::sync::Arc;

use crate::errors::Error;
use crate::toolset::tool_request::ToolRequest;
use crate::toolset::tool_version::ResolveOptions;
use crate::toolset::{ToolSource, ToolVersion};
use crate::{cli::args::BackendArg, config::Config};

/// represents several versions of a tool for a particular plugin
#[derive(Debug, Clone)]
pub(crate) struct ToolVersionList {
    pub backend: Arc<BackendArg>,
    pub versions: Vec<ToolVersion>,
    pub requests: Vec<ToolRequest>,
    pub source: ToolSource,
}

impl ToolVersionList {
    pub(crate) fn new(backend: Arc<BackendArg>, source: ToolSource) -> Self {
        Self {
            backend,
            versions: Vec::new(),
            requests: vec![],
            source,
        }
    }
    pub(crate) async fn resolve(
        &mut self,
        config: &Arc<Config>,
        opts: &ResolveOptions,
    ) -> eyre::Result<()> {
        self.versions.clear();
        for tvr in &mut self.requests {
            // Only use special options (latest_versions) for requests that
            // explicitly specify "latest". This ensures `mise x node@20 npm@latest` only
            // fetches latest for npm, not node.
            // However, we always respect the caller's use_locked_version setting.
            let request_opts = if tvr.version() == "latest"
                || tvr
                    .ba()
                    .backend()
                    .is_ok_and(|backend| backend.is_rolling_channel(&tvr.version()))
            {
                opts.clone()
            } else {
                ResolveOptions {
                    latest_versions: false,
                    use_locked_version: opts.use_locked_version,
                    ..opts.clone()
                }
            };
            match tvr.resolve(config, &request_opts).await {
                Ok(v) => self.versions.push(v),
                Err(err) => {
                    return Err(Error::FailedToResolveVersion {
                        tr: Box::new(tvr.clone()),
                        ts: self.source.clone(),
                        source: err,
                    }
                    .into());
                }
            }
        }
        Ok(())
    }

    pub(crate) fn os_supported_versions(&self) -> impl Iterator<Item = &ToolVersion> {
        self.versions
            .iter()
            .filter(|tv| tv.request.is_os_supported())
    }

    pub(crate) fn os_supported_requests(&self) -> impl Iterator<Item = &ToolRequest> {
        self.requests.iter().filter(|tvr| tvr.is_os_supported())
    }
}

