    fn activate_shims(&self, shell: &dyn Shell, mise_bin: &Path) -> std::io::Result<()> {
        let exe_dir = mise_bin.parent().unwrap();
        let user_shims = dirs::shims();
        let system_shims = dirs::system_shims();
