impl Toolset {
    async fn missing_lazy_bin_provider(
        &self,
        config: &Arc<Config>,
        bin_name: &str,
    ) -> Result<Option<ToolVersion>> {
        let mut providers = self
            .list_missing_versions(config)
            .await
            .into_iter()
            .filter_map(|tv| {
                let options = tv.request.options();
                if options.lazy == Some(true) {
                    match tv.request.lazy_bins() {
                        Ok(Some(bins)) if bins.iter().any(|bin| bin == bin_name) => Some(Ok(tv)),
                        Ok(_) => None,
                        Err(err) => Some(Err(err)),
                    }
                } else if tv.ba().matches_bin_name(bin_name)
                    || tv
                        .ba()
                        .registry_tool()
                        .is_some_and(|tool| tool.provides_bin(bin_name))
                {
                    Some(Ok(tv))
                } else {
                    None
                }
            })
            .map(|tv| tv.and_then(|tv| Ok((tv.backend()?, tv))))
            .collect::<Result<Vec<_>>>()?;
        Self::sort_by_overrides(&mut providers)?;
        Ok(providers
            .into_iter()
            .next()
            .and_then(|(_, tv)| (tv.request.options().lazy == Some(true)).then_some(tv)))
    }

    pub(crate) async fn has_missing_lazy_bin_provider(
        &self,
        config: &Arc<Config>,
        bin_name: &str,
    ) -> Result<bool> {
        Ok(self
            .missing_lazy_bin_provider(config, bin_name)
            .await?
            .is_some())
    }

    pub(crate) async fn install_missing_lazy_bin(
        &mut self,
        config: &mut Arc<Config>,
        bin_name: &str,
    ) -> Result<Option<Vec<ToolVersion>>> {
        let Some(tv) = self.missing_lazy_bin_provider(config, bin_name).await? else {
            return Ok(None);
        };
        let install_dir = tv.request.source().path().and_then(|path| {
            (crate::config::provenance::ConfigProvenance::from_path(path).scope()
                == crate::config::provenance::ConfigFileScope::System)
                .then(|| Settings::get().system_installs_dir().to_path_buf())
        });
        let install_options = InstallOptions {
            reason: "lazy shim".into(),
            install_dir: install_dir.filter(|dir| dir != *crate::dirs::INSTALLS),
            ..Default::default()
        };
        let installed = self
            .install_all_versions(config, vec![tv.request.clone()], &install_options)
            .await
            .wrap_err_with(|| {
                install_options.install_dir.as_ref().map_or_else(
                    || format!("failed to install lazy tool {}", tv.style()),
                    |dir| {
                        format!(
                            "failed to install lazy tool {} into {}. Preinstall it with appropriate privileges or set system_installs_dir to a writable directory",
                            tv.style(),
                            crate::file::display_path(dir)
                        )
                    },
                )
            })?;
        if !installed.is_empty() {
            let ts = config.get_toolset().await?;
            config::rebuild_shims_and_runtime_symlinks(
                config,
                ts,
                &installed,
                crate::lockfile::LockfileUpdateMode::Normal,
            )
            .await?;
        }
        Ok(Some(installed))
    }

    pub(crate) async fn should_install_missing_registry_bin_provider(
        &self,
        config: &Arc<Config>,
        bin_name: &str,
    ) -> Result<bool> {
        let mut providers = vec![];
        for (backend, tv) in self.list_current_versions() {
            if backend.is_version_installed(config, &tv, true) {
                if backend
                    .which(config, &tv, bin_name)
                    .await
                    .ok()
                    .flatten()
                    .is_some()
                {
                    providers.push((backend, tv));
                }
            } else if REGISTRY
                .get(&tv.ba().short)
                .is_some_and(|tool| tool.provides_bin(bin_name))
                && match &Settings::get().auto_install_disable_tools {
                    Some(disable_tools) => !disable_tools.contains(&tv.ba().short),
                    None => true,
                }
            {
                providers.push((backend, tv));
            }
                prefix,
                require_prefix_boundary,
                request_options: &request_options,
                legacy_options_fallback,
                backend: backend.as_deref(),
                selection_options: &self.options(),
            },
        )
    }

    pub(crate) fn local_resolve(&self, config: &Config, v: &str) -> eyre::Result<Option<String>> {
        if let Some(lt) = self.lockfile_resolve(config)? {
            return Ok(Some(lt.version));
        }
        if let Some(backend) = backend::get(self.ba()) {
            let matches = backend.list_installed_versions_matching(v);
            if matches.iter().any(|m| m == v) {
                return Ok(Some(v.to_string()));
            }
            if let Some(v) = matches.last() {
                return Ok(Some(v.to_string()));
            }
        }
        Ok(None)
    }

    pub(crate) async fn resolve(
        &self,
        config: &Arc<Config>,
        opts: &ResolveOptions,
    ) -> Result<ToolVersion> {
        ToolVersion::resolve(config, self.clone(), opts).await
    }

    pub(crate) fn resolve_options(&self, opts: &ResolveOptions) -> Result<ResolveOptions> {
        let minimum_release_age = self.options().minimum_release_age().map(str::to_string);
        let mut opts = opts.clone();
        opts.apply_before_date_for_tool(self.ba(), minimum_release_age.as_deref())?;
        Ok(opts)
    }

    pub(crate) fn is_os_supported(&self) -> bool {
        if let Some(os_list) = self.os() {
            let matched = os_list
                .iter()
                .any(|entry| crate::cli::version::os_selector_matches(entry));
            if !matched {
                return false;
            }
        }
        self.ba().is_os_supported()
    }
}

/// Reject version strings that contain shell-quote-breaking characters,
/// control characters, or path-traversal sequences. Version strings flow into
/// install path names and (for vfox plugins) into `ctx.version` / `ctx.rootPath`
/// values that downstream Lua hooks often interpolate into shell commands.
///
/// The deny list is the minimum set of characters that can break out of either
/// a single- or double-quoted shell string, or that trigger expansion *inside*
/// double quotes: quotes themselves, backslash, backtick, and `$`. Plus control
/// characters (newlines split shell tokens) and `..` (filesystem traversal).
/// Everything else is allowed so legitimate version vocabulary (npm-style
/// semver ranges like `>=20 <21 || >=22` or `^1.0.0`, dates, channel names,
/// `lts/hydrogen`, etc.) continues to work — those characters are only
/// dangerous in *unquoted* shell context, which cannot occur without one of
/// the rejected expansion characters appearing first. Leading dashes are also
/// rejected so backend install tools cannot mistake a version for a CLI flag.
fn validate_version_string(s: &str) -> Result<()> {
    if s.is_empty() {
        return Ok(());
    }
    if s.starts_with('-') {
        bail!("invalid tool version {s:?}: must not start with '-'");
    }
    if s.contains("..") {
        bail!("invalid tool version {s:?}: contains path-traversal sequence");
    }
    if let Some(c) = s.chars().find(|c| is_forbidden_version_char(*c)) {
        bail!("invalid tool version {s:?}: contains forbidden character {c:?}");
    }
    Ok(())
}

