    pub(crate) fn runtime_pathname(&self) -> Option<String> {
        let pathname = match &self.request {
            ToolRequest::Version { version, .. } if version != &self.version => version.clone(),
            ToolRequest::Prefix { prefix, .. } => prefix.clone(),
            ToolRequest::Sub { .. } if self.request.version() != self.version => {
                self.request.version()
            }
            _ => return None,
        };
        Some(pathname.replace([':', '/'], "-"))
    }
    async fn resolve_version(
        config: &Arc<Config>,
        request: ToolRequest,
        v: &str,
        opts: &ResolveOptions,
    ) -> Result<ToolVersion> {
        let backend = request.backend()?;
        let v = config.resolve_alias(&backend, v).await?;

        // Re-check the lockfile after alias resolution (e.g., "lts" → "24")
        // The initial lockfile check in resolve() uses the unresolved alias which
        // won't match lockfile entries like "24.13.0".starts_with("lts")
        // If the alias resolved to a `prefix:` selector, match on the bare
        // prefix with separator-boundary matching — the lockfile stores
        // concrete versions (#5781). Config-level `prefix:...` strings always
        // parse into ToolRequest::Prefix, so a Version request only carries
        // this scheme via an alias.
        let (lock_query, lock_prefix_boundary) = match v.strip_prefix("prefix:") {
            Some(p) => (p, true),
            None => (v.as_str(), false),
        };
        if opts.use_locked_version
            && !has_linked_version(request.ba())
            && let Some(lt) =
                request.lockfile_resolve_with_prefix(config, lock_query, lock_prefix_boundary)?
        {
            return Ok(Self::from_lockfile(request.clone(), lt));
        }
        let settings = Settings::get();
        let tool_config_locked = config.tool_config_locked(request.source());
        let invocation_locked = config.invocation_locked_for(request.source(), settings.locked);
        if (invocation_locked || tool_config_locked)
            && opts.use_locked_version
            && settings.lockfile_enabled()
            && !has_linked_version(request.ba())
            && request.source().path().is_some()
        {
            let hint = if tool_config_locked && !invocation_locked {
                "Run `mise lock` to update the lockfile, or disable `tool_config.locked`"
            } else {
                "Run `mise install` without --locked to update the lockfile"
            };
            bail!(
                "{}@{} is not in the lockfile\nhint: {hint}",
                request.ba().short,
                request.version()
            );
        }

        match v.split_once(':') {
            Some((ref_type @ ("ref" | "tag" | "branch" | "rev"), r)) => {
                return Ok(Self::resolve_ref(
                    r.to_string(),
                    ref_type.to_string(),
                    &request,
                ));
            }
            Some(("path", p)) => {
                return Self::resolve_path(PathBuf::from(p), &request);
            }
            Some(("prefix", p)) => {
                    if let Some(tr) = in_flight.remove(&e.id()) {
                        attempted_failures.push(tr.clone());
                        failed.push((tr.clone(), eyre::eyre!("Installation task panicked: {e:#}")));
                        tool_deps.lock().await.complete_failure(&tr);
                    } else {
                        warn!("Task panicked but tool request not found: {e:#}");
                    }
                }
            }
        }

        // Add blocked tools to failures
        let blocked = tool_deps.lock().await.blocked_tools();
        for tr in blocked {
            failed.push((tr.clone(), eyre::eyre!("Skipped due to failed dependency")));
            MultiProgressReport::get().footer_inc(1);
        }

        // Sort installed versions by original request order to preserve user's intended ordering
        installed.sort_by_key(|tv| {
            let key = tool_key(&tv.request);
            request_order.get(&key).copied().unwrap_or(usize::MAX)
        });

        (installed, failed, attempted_failures)
    }

    /// Install a single tool
    async fn install_single_tool(
        config: &Arc<Config>,
        ts: &Arc<Toolset>,
        tr: &ToolRequest,
        opts: &Arc<InstallOptions>,
    ) -> Result<ToolVersion> {
        let mpr = MultiProgressReport::get();
        let pre_resolve_backend = tr.backend()?;
        backend::ensure_backend_enabled(&pre_resolve_backend.get_type())?;
        let mut resolve_options = opts.resolve_options.clone();
        if should_refresh_remote_versions(tr, &pre_resolve_backend, &resolve_options) {
            resolve_options.refresh_remote_versions = true;
        }
        let mut tv = tr.resolve(config, &resolve_options).await?;
        let backend = tv.backend()?;
        backend::ensure_backend_enabled(&backend.get_type())?;
        if let Some(dir) = &opts.install_dir {
            let tool_dir_name = tv.ba().tool_dir_name();
            tv.install_path = Some(dir.join(tool_dir_name).join(tv.tv_pathname()));
            tv.install_path_is_explicit = true;
        }
