[default_tool_versions_filename]
default = ".tool-versions"
description = "The default .tool-versions filename read. This will not ignore .tool-versions—use override_tool_versions_filename for that. This must be an env var."
env = "MISE_DEFAULT_TOOL_VERSIONS_FILENAME"
env_only = true
type = "String"

[disable_backends]
default = []
description = "Backends to disable for new installs, such as `asdf`, `pipx`, or a vfox-backend plugin name. This does not uninstall or disable tools already installed with those backends."
env = "MISE_DISABLE_BACKENDS"
parse_env = "list_by_comma"
rust_type = "Vec<String>"
type = "ListString"

[disable_default_registry]
description = "Disable the default mapping of short tool names like `php` -> `asdf:mise-plugins/asdf-php`. This parameter disables only for the backends `vfox` and `asdf`."
env = "MISE_DISABLE_DEFAULT_REGISTRY"
type = "Bool"

[disable_hints]
default = []
description = "Turns off helpful hints when using different mise features"
env = "MISE_DISABLE_HINTS"
parse_env = "set_by_comma"
rust_type = "BTreeSet<String>"
type = "SetString"

[disable_tools]
default = []
description = "Tools defined in mise.toml that should be ignored"
env = "MISE_DISABLE_TOOLS"
parse_env = "set_by_comma"
rust_type = "BTreeSet<String>"
type = "SetString"

[dotfiles.default_mode]
default = "symlink"
description = "Default mode for dotfile entries when mode is omitted. Options: `symlink`, `symlink-each`, `copy`, `template`."
env = "MISE_DOTFILES_DEFAULT_MODE"
type = "String"

[dotfiles.root]
default = "~/.dotfiles"
description = "Root directory used for implied dotfile sources."
env = "MISE_DOTFILES_ROOT"
type = "Path"

[dotnet.cli_telemetry_optout]
description = "Set DOTNET_CLI_TELEMETRY_OPTOUT to opt out of .NET CLI telemetry."

Set to "false" to disable idiomatic version file parsing.
"""
env = "MISE_IDIOMATIC_VERSION_FILE"
hide = true
optional = true
type = "Bool"

[idiomatic_version_file_disable_files]
default = []
description = "Specific idiomatic version files to disable for a tool."
docs = """
Use `tool:filename` pairs to exclude individual idiomatic version files without disabling
other files for the tool or other tools that read the same file.

For example, this keeps `.nvmrc` enabled for node while preventing node from reading
`devEngines.runtime` in `package.json`:

    mise settings add idiomatic_version_file_disable_files node:package.json
"""
env = "MISE_IDIOMATIC_VERSION_FILE_DISABLE_FILES"
parse_env = "set_by_comma"
rust_type = "BTreeSet<String>"
type = "SetString"

[idiomatic_version_file_disable_tools]
default = []
deprecated = "This has been replaced with the idiomatic_version_file_enable_tools setting."
description = "Specific tools to disable idiomatic version files for."
env = "MISE_IDIOMATIC_VERSION_FILE_DISABLE_TOOLS"
hide = true
parse_env = "set_by_comma"
rust_type = "BTreeSet<String>"
type = "SetString"

[idiomatic_version_file_enable_tools]
default = []
description = "Specific tools to enable idiomatic version files for like .node-version, .ruby-version, etc."
docs = """
By default, idiomatic version files are disabled. You can enable them for specific tools with this setting.

For example, to enable idiomatic version files for node and python:

    mise settings add idiomatic_version_file_enable_tools node
    mise settings add idiomatic_version_file_enable_tools python

See [Idiomatic Version Files](/configuration.html#idiomatic-version-files) for more information.
"""
env = "MISE_IDIOMATIC_VERSION_FILE_ENABLE_TOOLS"
parse_env = "set_by_comma"
rust_type = "BTreeSet<String>"
type = "SetString"

[idiomatic_version_file_ignore_minimum_versions]
default = false
description = "Ignore idiomatic version file fields that only declare a minimum compatible version."
docs = """
Some idiomatic version files carry a *minimum* compatible version rather than the version the
project is built with. mise used to resolve those, which is wrong -- a floor says nothing about
which version a project is developed against. They are deprecated and warn; set this to opt into
the final behavior now, which ignores them and silences the warning:
          "description": "Libc implementation to use for precompiled Linux binaries.",
          "type": "string",
          "enum": ["glibc", "gnu", "musl"]
        },
        "libgit2": {
          "default": true,
          "description": "Use libgit2 for git operations, set to false to shell out to git.",
          "type": "boolean"
        },
        "locked": {
          "default": false,
          "description": "Require lockfile URLs to be present during installation.",
          "type": "boolean"
        },
        "locked_scopes": {
          "default": ["global", "project", "system"],
          "description": "Config scopes where invocation-wide locked mode is enforced.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "locked_verify_provenance": {
          "default": false,
          "description": "Re-verify provenance at install time even when the lockfile already has provenance.",
          "type": "boolean"
        },
        "lockfile": {
          "description": "Create and read lockfiles for tool versions.",
          "type": "boolean"
        },
        "lockfile_platforms": {
          "description": "Platforms to target in lockfile operations.",
          "type": "array",
          "items": {
            "type": "string"
                } else {
                    "they are"
                },
                use_cmds.join("\n"),
            );
        }

        install_error?;
        Ok(())
    }

    fn install_opts(&self) -> Result<InstallOptions> {
        let install_dir = if self.system {
            Some(Settings::get().system_installs_dir().to_path_buf())
        } else {
            self.shared.clone()
        }
        .map(|path| path.absolutize().map(|path| path.into_owned()))
        .transpose()?;
        Ok(InstallOptions {
            force: self.force,
            jobs: self.jobs,
            raw: self.raw,
            missing_args_only: false,
            include_lazy: self.tool.is_some() || self.include_lazy,
            resolve_options: ResolveOptions {
                use_locked_version: true,
                latest_versions: true,
                resolve_rolling_channels: false,
                prefer_exact_version: false,
                before_date: self.get_before_date()?,
                before_date_from_default: false,
                filter_installed_versions_by_release_date: false,
                offline: false,
                refresh_remote_versions: false,
                inactive: false,
            },
            dry_run: self.is_dry_run(),
            locked: Settings::get().locked,
            install_dir,
            yes: self.yes || Settings::get().yes,
            ..Default::default()
        })
    }

    /// Get the minimum_release_age cutoff from the CLI --minimum-release-age flag only.
    /// Per-tool and global setting fallbacks are handled in ToolRequest::resolve.
    fn get_before_date(&self) -> Result<Option<Timestamp>> {
        resolve_cli_minimum_release_age(self.minimum_release_age.as_deref())
    }

use std::path::PathBuf;

use crate::config::settings::Settings;
use crate::toolset::tool_version::ResolveOptions;

#[derive(Debug, Clone)]
pub(crate) struct InstallOptions {
    pub reason: String,
    pub force: bool,
    pub jobs: Option<usize>,
    pub raw: bool,
    /// only install missing tools if passed as arguments
    pub missing_args_only: bool,
    /// install lazy declarations because the user explicitly named a tool
    pub include_lazy: bool,
    /// completely disable auto-installation when auto_install setting is false
    pub skip_auto_install: bool,
    pub auto_install_disable_tools: Option<Vec<String>>,
    pub resolve_options: ResolveOptions,
    pub dry_run: bool,
    /// Only run hooks defined in global config files.
    pub global_hooks_only: bool,
    /// require lockfile URLs to be present; fail if not
    pub locked: bool,
    /// Override the install directory (e.g. for --system or --shared)
    pub install_dir: Option<PathBuf>,
    /// skip confirmation prompts (e.g. installing missing plugin system deps).
    /// Defaults to the global `yes` setting; `mise bootstrap --yes` also sets it.
    pub yes: bool,
}

impl Default for InstallOptions {
    fn default() -> Self {
        InstallOptions {
            jobs: Some(Settings::get().jobs),
            raw: Settings::get().raw,
            reason: "install".to_string(),
            force: false,
            missing_args_only: true,
            include_lazy: false,
            skip_auto_install: false,
            auto_install_disable_tools: Settings::get().auto_install_disable_tools.clone(),
            resolve_options: Default::default(),
            dry_run: false,
            global_hooks_only: false,
            locked: Settings::get().locked,
            install_dir: None,
            yes: Settings::get().yes,
        }
    }
}

