rust_type = "BTreeSet<PathBuf>"
type = "ListPath"

[ci]
default = "false"
description = "Set to true if running in a CI environment"
deserialize_with = "bool_string"
env = "CI"
global_only = true
hide = true
type = "Bool"

[color]
default = true
description = "Use color in mise terminal output"
env = "MISE_COLOR"
type = "Bool"

[color_theme]
default = "default"
description = "Theme for interactive prompts (auto/default, charm, base16, catppuccin, dracula)"
docs = """
Sets the color theme for interactive prompts like `mise run` task selection.
Available themes:

- `auto` (or `default`) - Auto-detect the terminal background (via `COLORFGBG`) and
  use a light-friendly theme (`base16`) on light terminals, otherwise `charm`
- `charm` - The charm theme, works well on dark terminals (no auto-detection)
- `base16` - Base16 theme, works well on light terminals
- `catppuccin` - Catppuccin theme
- `dracula` - Dracula theme

`default` is an alias for `auto`: when left unset (or set to `auto`/`default`), mise
auto-detects a light terminal background via `COLORFGBG` and switches to `base16` for
readability. Set an explicit theme (e.g. `charm`) to disable auto-detection.

When colors are disabled (`color=false`, `NO_COLOR`, or `CLICOLOR=0`), interactive
prompts are rendered without any styling regardless of this setting.
"""
enum = ["auto", "default", "charm", "base16", "catppuccin", "dracula"]
env = "MISE_COLOR_THEME"
type = "String"

[conda.channel]
default = "conda-forge"
description = "Default channel for conda packages."
docs = """
Default conda channel when installing packages with the conda backend.
Override per-package with `conda:package[channel=bioconda]`.

The most common channels are:
fn aqua_registry_files_code(
    registries: &[AquaPackageRegistry],
    packages_dir: &Path,
) -> Result<String> {
    let mut used_stems = HashMap::new();
    let mut entries = registries
        .iter()
        .map(|registry| {
            let stem = aqua_package_file_stem(&registry.id);
            if let Some(other_id) = used_stems.insert(stem.clone(), registry.id.as_str()) {
                return Err(eyre!(
                    "baked aqua registry package filename collision for {other_id:?} and {:?}: {stem}",
                    registry.id
                ));
            }
            let filename = format!("{stem}.rkyv");
            let path = packages_dir.join(filename);
            fs::write(&path, &registry.content)?;
            Ok((registry.id.clone(), path))
        })
        .collect::<Result<Vec<_>>>()?;
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    Ok(aqua_registry_bytes_map_code(&entries))
}

fn aqua_registry_bytes_map_code(entries: &[(String, PathBuf)]) -> String {
    let mut map = phf_codegen::Map::new();
    let mut values = Vec::new();
    for (key, path) in entries {
        values.push((
            key.clone(),
            format!(
                "include_bytes!({:?}).as_slice()",
                path.display().to_string()
            ),
        ));
    }
    for (key, value) in &values {
        map.entry(key, value);
    }
    map.build().to_string()
}

/// Hashes the canonical package ID with FNV-1a 64-bit to generate compact,
/// deterministic baked package filenames without leaking path separators.
fn aqua_package_file_stem(id: &str) -> String {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in id.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn aqua_registry_aliases_code(registries: &[AquaPackageRegistry]) -> Result<String> {
    let canonical_ids = registries
        .iter()
